insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$piranga$q$, $q$https://www.diariomunicipal.com.br/amm-mg/materia/BE4D4487 (Dec. 3.002/2020, Diário Oficial dos Municípios Mineiros, 03/02/2020)$q$, $q$Ato oficial de Piranga: domínio público (Lei 9.610/1998, art. 8º, IV). Polígono da área urbana derivado do OpenStreetMap (ODbL 1.0, © colaboradores do OSM).$q$, 2, $q$Dec. 3.002/2020, art. 2º, parágrafo único: 5 eixos ou mais das 11h às 17h e 3 eixos ou mais das 22h às 5h, todos os dias, na 'área urbana', até que exista o desvio. Área urbana não delimitada no ato: polígono aproximado. Vigência depende de um fato (o desvio) não confirmado: confiança média.$q$);
